package main

import (
	"bytes"
	"fmt"
	"go/format"
	"math"
	"slices"
)

// contractNamesFile is the generated label table of contract.DeviceTypeName.
// devicegen writes it, not script/generate_matter_schema.go: that generator
// writes only into schema/, a package wholly generated, while devicegen
// already writes generated files into a package that is otherwise
// hand-kept (device/) and carries the staleness guard
// (TestCommittedFilesAreCurrent) the table needs. contract/ imports the
// standard library only, so it cannot read schema.DeviceTypeNames at run
// time; the table is generated from the same snapshot instead.
const (
	contractDir       = "contract"
	contractNamesFile = "devicetype_names_gen.go"
)

// labelOverrides are the operator-facing labels contract.DeviceTypeName
// returned from its hand-kept table before the table was generated
// (issue #57). Where the hand-kept label differs from the matter.js name,
// the hand-kept spelling stays: hosts group, filter and search their
// exposure rows by it. Every other device type is labelled with its
// matter.js name, as schema.DeviceTypeName gives it.
var labelOverrides = map[uint32]string{
	0x000A: "Door Lock",               // matter.js "DoorLock"
	0x000F: "Generic Switch",          // matter.js "GenericSwitch"
	0x0015: "Contact Sensor",          // matter.js "ContactSensor"
	0x0027: "Mode Select",             // matter.js "ModeSelect"
	0x002C: "Air Quality Sensor",      // matter.js "AirQualitySensor"
	0x002D: "Air Purifier",            // matter.js "AirPurifier"
	0x0043: "Water Leak Detector",     // matter.js "WaterLeakDetector"
	0x0073: "Laundry Washer",          // matter.js "LaundryWasher"
	0x0074: "Robotic Vacuum Cleaner",  // matter.js "RoboticVacuumCleaner"
	0x0076: "Smoke / CO Alarm",        // matter.js "SmokeCoAlarm"
	0x007A: "Extractor Hood",          // matter.js "ExtractorHood"
	0x007C: "Laundry Dryer",           // matter.js "LaundryDryer"
	0x0100: "On/Off Light",            // matter.js "OnOffLight"
	0x0101: "Dimmable Light",          // matter.js "DimmableLight"
	0x0106: "Light Sensor",            // matter.js "LightSensor"
	0x0107: "Occupancy Sensor",        // matter.js "OccupancySensor"
	0x010A: "On/Off Plug-in Unit",     // matter.js "OnOffPlugInUnit"
	0x010C: "Color Temperature Light", // matter.js "ColorTemperatureLight"
	0x010D: "Extended Color Light",    // matter.js "ExtendedColorLight"
	0x0202: "Window Covering",         // matter.js "WindowCovering"
	0x0302: "Temperature Sensor",      // matter.js "TemperatureSensor"
	0x0305: "Pressure Sensor",         // matter.js "PressureSensor"
	0x0306: "Flow Sensor",             // matter.js "FlowSensor"
	0x0307: "Humidity Sensor",         // matter.js "HumiditySensor"
	0x0510: "Electrical Sensor",       // matter.js "ElectricalSensor"; advertised by contract.MeasurementElectrical
}

// generateContractNames renders contract/devicetype_names_gen.go: every
// snapshot device type with an id, by id, labelled with its matter.js name
// or its labelOverrides entry.
func (g *generator) generateContractNames() (*output, error) {
	type entry struct {
		id      uint32
		label   string
		matterJ string
	}
	var entries []entry
	for _, dt := range g.snap.DeviceTypes {
		if dt.ID == nil {
			continue
		}
		if *dt.ID > math.MaxUint16 {
			return nil, fmt.Errorf("device type %s: id 0x%X does not fit contract's uint16", dt.Name, *dt.ID)
		}
		e := entry{id: *dt.ID, label: dt.Name}
		if o, ok := labelOverrides[*dt.ID]; ok {
			e.label, e.matterJ = o, dt.Name
		}
		entries = append(entries, e)
	}
	slices.SortFunc(entries, func(a, b entry) int { return int(a.id) - int(b.id) })
	var w bytes.Buffer
	w.WriteString("// SPDX-License-Identifier: Apache-2.0\n// Copyright (C) 2026 SukramJ.\n\n")
	w.WriteString("// Code generated by script/devicegen from parity/schema.json. DO NOT EDIT.\n\n")
	w.WriteString("package contract\n\n")
	w.WriteString("// deviceTypeNames holds the labels [DeviceTypeName] returns: every device\n")
	w.WriteString("// type of the matter.js snapshot, under its matter.js name, or under the\n")
	w.WriteString("// operator-facing label script/devicegen's labelOverrides keeps (the\n")
	w.WriteString("// matter.js name then follows in a comment).\n")
	w.WriteString("var deviceTypeNames = map[uint16]string{\n")
	for _, e := range entries {
		fmt.Fprintf(&w, "\t0x%04X: %q,", e.id, e.label)
		if e.matterJ != "" {
			fmt.Fprintf(&w, " // %s", e.matterJ)
		}
		w.WriteString("\n")
	}
	w.WriteString("}\n")
	out, err := format.Source(w.Bytes())
	if err != nil {
		return nil, err
	}
	return &output{File: contractNamesFile, Source: out}, nil
}
